  const withOf = x => '';

  /* ---------- Reseña ---------- */
  const paidOf = x => money(x.tot || 0);
  const cita = (s, bid, cid) => { const L = (s.tped || []).filter(x => x.own === bid && x.st === 'done'), x = (cid && L.find(y => y.id === cid)) || L[L.length - 1] || null; return x ? { ...x, withL: withOf(x), total: 0, paid: paidOf(x) } : null; };
