  function pool(b, ctA, isCita, es) { const L = [].concat(...SL.svcs(b.id).map(g => g[2])); return (isCita && ctA ? [es ? ctA.svc : ctA.svcEn] : []).concat(L.map(it => es ? it.n : it.ne || it.n)).filter((k, i, a) => a.indexOf(k) === i).slice(0, 6); }
  function draft(F, isCita, ctA, es) { return { src: isCita ? 'cita' : 'vis', hot: null, val: null, taste: null, late: null, wait: '', lateK: '', asked: null, price: null, clean: null, trato: F.trato, whoOk: null, pro: isCita && ctA ? ctA.withL : '', cid: isCita && ctA ? ctA.id : '',
    svc: '', caja: F.clean == null ? null : F.clean === -1 ? 0 : 1, hay: F.price == null ? null : F.price, talla: F.asked == null ? null : F.asked === 1 ? 1 : 0, apa: isCita ? (F.whoOk == null ? null : F.whoOk) : null, dev: F.wait === 'a' ? 1 : F.wait === 'c' ? 0 : null }; }
  function fix(V, C, s, es, b, isCita, ctA) { const E2 = (a, c) => es ? a : c;
    return { ...V, tmK: E2('TU APARTADO', 'YOUR HOLD'), tmNote: E2("Lo que apartaste y pagaste sale de To'Latino. No se edita.", "What you held and paid comes from To'Latino. It cannot be edited."),
      meta: (b.name + (isCita && ctA ? E2(' · APARTADO #', ' · HOLD #') + ctA.id : '')).toUpperCase(),
      lowT: E2('La reseña no devuelve dinero. Si en la caja cobraron más o no guardaron tu apartado, pídelo en Ayuda con la compra.', 'A review does not refund money. If the register charged more or they did not hold your items, ask in Purchase help.'),
      onHelpOrd: () => ctA ? startHelp(C, ctA.id) : C.encargo('APP-NEG-TIENDA-AYUDA', 'APP-NEG-RESENA', b.name, E2('Ayuda con la compra', 'Purchase help')),
      lbl: { ...V.lbl, srcNote: E2("Solo sale verificada si apartaste por To'Latino.", "It only shows as verified if you held through To'Latino."), aspK: E2('LO QUE IMPORTA EN UNA TIENDA', 'WHAT MATTERS AT A STORE'), recK: E2('¿QUÉ SERVICIO RECOMIENDAS?', 'WHICH SERVICE DO YOU RECOMMEND?'), recS: E2('Opcional. Sale en tu reseña.', 'Optional. Shows in your review.'),
        textPh: NOMED[es ? 0 : 1], helpOrd: E2('Ir a Ayuda con la compra', 'Go to Purchase help') } }; }

  /* ---------- Ayuda con la cita ---------- */
  const RSN = [['caja', 'Cobraron más en la caja', 'Charged more at the register', 1], ['apa', 'No guardaron el apartado', 'They did not hold my items', 0], ['talla', 'Talla o artículo equivocado', 'Wrong size or item', 0], ['cambio', 'No aceptan el cambio', 'They refuse the exchange', 1], ['dano', 'Llegó dañado', 'It arrived damaged', 1], ['otro', 'Otra cosa', 'Something else', 0]];
